<?php
namespace App\Http\Controllers;
use App\Models\Address; use Illuminate\Http\Request;
class AccountController extends Controller { public function index(){return view('account.dashboard',['orders'=>auth()->user()->orders()->latest()->take(5)->get(),'addresses'=>auth()->user()->addresses()->latest()->get()]);} public function saveAddress(Request $request){$data=$request->validate(['label'=>'required|string|max:50','name'=>'required|string|max:120','phone'=>'required|string|max:30','address'=>'required|string|max:255','city'=>'required|string|max:100','state'=>'required|string|max:100']); $data['user_id']=auth()->id(); if($request->boolean('is_default')) Address::where('user_id',auth()->id())->update(['is_default'=>false]); Address::create($data+['is_default'=>$request->boolean('is_default')]); return back()->with('success','Address saved.');} public function deleteAddress(Address $address){abort_unless($address->user_id===auth()->id(),403);$address->delete();return back()->with('success','Address removed.');} }
